    const weeks = dispot.value?.deposit_cycle || 2  // 기본값 2주
    const today = new Date()
    const date = new Date(today)
    date.setDate(today.getDate() + weeks * 7)

    // YYYY-MM-DD 포맷
    maturityDate.value = date.toISOString().split('T')[0]
  }
}


